import React, { useState, useCallback } from 'react';
import { Card, Stack, ButtonGroup, Button, Calendar } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date) => void;
  initialDate?: Date;
}

function startOfDay(date: Date): Date {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}

function addDays(date: Date, days: number): Date {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

const ReportDatePicker: React.FC<ReportDatePickerProps> = ({
  onChange,
  initialDate,
}) => {
  const [selectedDate, setSelectedDate] = useState<Date>(
    startOfDay(initialDate ?? new Date())
  );

  const handleSelect = useCallback(
    (date: Date) => {
      const normalized = startOfDay(date);
      setSelectedDate(normalized);
      onChange?.(normalized);
    },
    [onChange]
  );

  const quickOptions = [
    { label: 'Сегодня', getDate: () => startOfDay(new Date()) },
    { label: 'Вчера', getDate: () => addDays(startOfDay(new Date()), -1) },
    {
      label: 'Неделя назад',
      getDate: () => addDays(startOfDay(new Date()), -7),
    },
  ];

  return (
    <Card className="jx-p-md">
      <Stack direction="column" gap="md">
        <ButtonGroup>
          {quickOptions.map((option) => {
            const optionDate = option.getDate();
            const isActive =
              optionDate.getTime() === selectedDate.getTime();
            return (
              <Button
                key={option.label}
                variant={isActive ? 'primary' : 'secondary'}
                onClick={() => handleSelect(optionDate)}
              >
                {option.label}
              </Button>
            );
          })}
        </ButtonGroup>
        <Calendar
          mode="single"
          value={selectedDate}
          onChange={(date: Date) => handleSelect(date)}
        />
      </Stack>
    </Card>
  );
};

export default ReportDatePicker;

